import{u,o as a,c as i,j as t,k as s,F as n,a8 as l,e as q,p as d}from"./chunks/framework.fPNBP_58.js";const c=["markdown-url"],h={"data-allow-mismatch":"",style:{display:"none"}},b=JSON.parse('{"title":"Climate Change Explorer for Tourism","description":"","frontmatter":{"layout":"page"},"headers":[],"params":{"narrative":"ccet-use-case-1","file":"https://gtif-austria.github.io/public-narratives/ccet-use-case-1.md","title":"Climate Change Explorer for Tourism"},"relativePath":"narratives/ccet-use-case-1.md","filePath":"narratives/[narrative].md"}'),m={name:"narratives/ccet-use-case-1.md"},v=Object.assign(m,{setup(p){const e=d(!0);e.value=!1;const{params:r}=u();return(g,o)=>(a(),i("div",null,[t("client-only",null,[t("eox-storytelling",{"show-nav":"","markdown-url":s(r).file,"show-hero-scroll-indicator":"","show-map-loading-indicator":"",class:"full-width",style:{transform:"translateY(calc(var(--vp-nav-height) - 2px))","margin-top":"calc(var(--vp-nav-height) * -1 - 90px + 48px)","margin-bottom":"var(--vp-nav-height)","--eox-storytelling-hero-height":"auto"}},null,8,c)]),t("div",h,[e.value?(a(),i(n,{key:0},[o[0]||(o[0]=l(' --- cover-image: https://raw.githubusercontent.com/GTIF-Austria/public-narratives/d00b1ba0ec630812811f0fb37cd6df9f655fd8a8/assets/MichaelaLandauer/20260929121021-1790865830383.jpg domain: Climate Change &amp; Tourism provider: GeoVille,Austria Tourism --- <h1 id="climate-change-explorer-for-tourism" tabindex="-1">Climate Change Explorer for Tourism <a class="header-anchor" href="#climate-change-explorer-for-tourism" aria-label="Permalink to &quot;Climate Change Explorer for Tourism &lt;!--{ as=&quot;img&quot; mode=&quot;hero&quot; src=&quot;https://raw.githubusercontent.com/GTIF-Austria/public-narratives/d00b1ba0ec630812811f0fb37cd6df9f655fd8a8/assets/MichaelaLandauer/20260929121021-1790865830383.jpg&quot; }--&gt;&quot;">​</a></h1><h3 id="use-case-1-climate-indicators" tabindex="-1">Use Case 1 - Climate Indicators <a class="header-anchor" href="#use-case-1-climate-indicators" aria-label="Permalink to &quot;Use Case 1 - Climate Indicators&quot;">​</a></h3><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The Climate Change Explorer for Tourism (CCET) is a joint initiative by <a href="https://www.geoville.com/" target="_blank" rel="noreferrer"><strong>GeoVille</strong></a>, <a href="https://b2b.austria.info/de-at/" target="_blank" rel="noreferrer"><strong>Österreich Werbung</strong></a>, <a href="https://eox.at/" target="_blank" rel="noreferrer"><strong>EOX</strong></a> and <a href="https://www.brz.gv.at/" target="_blank" rel="noreferrer"><strong>BRZ</strong></a> within Digital Twin Austria (GTIF-AT EA), giving Austria&#39;s tourism regions a user-friendly picture of climate change impacts and hazards. This page looks at the first of three use cases showcased in the tool.</p><h2 id="what-use-case-1-is-about" tabindex="-1">What Use Case 1 is about <a class="header-anchor" href="#what-use-case-1-is-about" aria-label="Permalink to &quot;What Use Case 1 is about&quot;">​</a></h2><p>This use case visualises projected climate changes using metrics that are directly relevant and useful for the tourism sector. It forms the foundation of the whole tool, addressing the question: how is the climate in a given region changing, and what long-term trends can be derived from it?</p><p><strong>Explore the Climate Indicators dataset <a href="https://gtif-austria.info/explore?indicator=climate_indicators" target="_blank" rel="noreferrer">HERE</a>.</strong></p><h2 id="exploring-climate-indicators-for-sustainable-tourism-planning-and-development" tabindex="-1">Exploring Climate Indicators for sustainable tourism planning and development <a class="header-anchor" href="#exploring-climate-indicators-for-sustainable-tourism-planning-and-development" aria-label="Permalink to &quot;Exploring Climate Indicators for sustainable tourism planning and development &lt;!--{ as=&quot;eox-map&quot; mode=&quot;tour&quot; position=&quot;right&quot; }--&gt;&quot;">​</a></h2><h3 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&lt;!--{ layers=&#39;[{&quot;type&quot;:&quot;Tile&quot;,&quot;properties&quot;:{&quot;id&quot;:&quot;cloudless-2025;:;EPSG:3857&quot;,&quot;title&quot;:&quot;EOxCloudless 2025&quot;,&quot;visible&quot;:true},&quot;source&quot;:{&quot;type&quot;:&quot;XYZ&quot;,&quot;url&quot;:&quot;https://{a-e}.s2maps-tiles.eu/wmts/1.0.0/s2cloudless-2025_3857/default/g/{z}/{y}/{x}.jpeg&quot;,&quot;projection&quot;:&quot;EPSG:3857&quot;,&quot;attributions&quot;:&quot;{ EOxCloudless 2025: &lt;a href=\\&quot;//s2maps.eu\\&quot; target=\\&quot;_blank\\&quot;&gt;Sentinel-2 cloudless - s2maps.eu&lt;/a&gt; by &lt;a href=\\&quot;//eox.at\\&quot; target=\\&quot;_blank\\&quot;&gt;EOX IT Services GmbH&lt;/a&gt; (Contains modified Copernicus Sentinel data 2025) }&quot;,&quot;tileGrid&quot;:{&quot;tileSize&quot;:[256,256]}}},{&quot;type&quot;:&quot;VectorTile&quot;,&quot;declutter&quot;:true,&quot;properties&quot;:{&quot;id&quot;:&quot;climate_indicators;:;2026-05-26T00:00:00Z;:;Climate Indicators;:;EPSG:3857&quot;,&quot;title&quot;:&quot;Climate Indicators&quot;},&quot;source&quot;:{&quot;type&quot;:&quot;VectorTile&quot;,&quot;format&quot;:{&quot;type&quot;:&quot;MVT&quot;},&quot;url&quot;:&quot;https://eoapi.workspace.gtif-eox.hub-otc.eox.at/vector/collections/public.climate_flat_geoms_master/tiles/WebMercatorQuad/{z}/{x}/{y}?scenario=rcp45&amp;metric=hot_days&amp;decade=2051_2060&quot;,&quot;projection&quot;:&quot;EPSG:3857&quot;},&quot;style&quot;:{&quot;variables&quot;:{&quot;scenario&quot;:&quot;rcp45&quot;,&quot;decade&quot;:&quot;2051_2060&quot;,&quot;month&quot;:&quot;jul&quot;,&quot;selected_elevation&quot;:&quot;full&quot;,&quot;selected_metric&quot;:&quot;hot_days&quot;,&quot;aggregation&quot;:&quot;mean&quot;,&quot;combined_prop&quot;:&quot;full_jul_mean&quot;,&quot;vmin&quot;:0,&quot;vmax&quot;:10},&quot;tooltip&quot;:[{&quot;id&quot;:&quot;tourism_region&quot;,&quot;title&quot;:&quot;Region&quot;},{&quot;id&quot;:&quot;scenario&quot;,&quot;title&quot;:&quot;Scenario&quot;},{&quot;id&quot;:&quot;metric&quot;,&quot;title&quot;:&quot;Metric&quot;},{&quot;id&quot;:&quot;full_jul_mean&quot;,&quot;title&quot;:&quot;Value (full | 2051_2060 jul)&quot;,&quot;decimals&quot;:2}],&quot;fill-color&quot;:[&quot;interpolate&quot;,[&quot;linear&quot;],[&quot;/&quot;,[&quot;-&quot;,[&quot;coalesce&quot;,[&quot;get&quot;,&quot;full_jul_mean&quot;],0],0],[&quot;-&quot;,10,0]],0,[254,224,210,1],0.143,[252,187,161,1],0.286,[252,146,114,1],0.429,[251,106,74,1],0.571,[239,59,44,1],0.714,[203,24,29,1],0.857,[165,15,21,1],1,[103,0,13,1]],&quot;stroke-color&quot;:&quot;black&quot;,&quot;stroke-width&quot;:1}},{&quot;type&quot;:&quot;Tile&quot;,&quot;properties&quot;:{&quot;id&quot;:&quot;overlay_bright;:;EPSG:3857&quot;,&quot;title&quot;:&quot;Overlay labels&quot;,&quot;visible&quot;:true},&quot;source&quot;:{&quot;type&quot;:&quot;XYZ&quot;,&quot;url&quot;:&quot;https://{a-e}.s2maps-tiles.eu/wmts/1.0.0/overlay_base_bright_3857/default/g/{z}/{y}/{x}.png&quot;,&quot;projection&quot;:&quot;EPSG:3857&quot;,&quot;attributions&quot;:&quot;{ Overlay: Data &amp;copy; &lt;a href=\\&quot;http://www.openstreetmap.org/copyright\\&quot; target=\\&quot;_blank\\&quot;&gt;OpenStreetMap&lt;/a&gt; contributors, Made with Natural Earth, Rendering &amp;copy; &lt;a href=\\&quot;//eox.at\\&quot; target=\\&quot;_blank\\&quot;&gt;EOX&lt;/a&gt; }&quot;,&quot;tileGrid&quot;:{&quot;tileSize&quot;:[256,256]}}}]&#39; zoom=&quot;7.5&quot; center=[13.64313143623767,47.36907650924309] projection=&quot;&quot; animationOptions={duration:500}}--&gt;&quot;">​</a></h3><h4 id="climate-indicators" tabindex="-1">Climate indicators <a class="header-anchor" href="#climate-indicators" aria-label="Permalink to &quot;Climate indicators&quot;">​</a></h4><p>Explore indicators such as hot days, tropical nights, ice or heavy precipitation days for sustainable tourism planning and development.</p><h2 id="the-data-behind-it" tabindex="-1">The data behind it <a class="header-anchor" href="#the-data-behind-it" aria-label="Permalink to &quot;The data behind it&quot;">​</a></h2><p>The indicators draw on the ÖKS15 climate projection dataset from <a href="https://data.hub.geosphere.at/group/oks15" target="_blank" rel="noreferrer">GeoSphere Austria</a>, calculated under two IPCC scenarios: RCP4.5 (a moderate pathway) and RCP8.5 (a pessimistic, high-emissions pathway). Temperature, precipitation and wind data are available at a spatial resolution of 1 km, on a daily basis, from 2011 to 2100.</p><p>For each decade between 1951 and 2100, the number of days meeting a given climatic criterion is counted for every month; these monthly counts are then averaged across all years within the respective decade to obtain a monthly climatology. The grid cell values are then spatially averaged within the defined spatial units – municipalities (LAU2 level), the three elevation zones - valley bottom (≤10th altitude percentile), mid-altitude (45th-55th altitude percentile), mountain peaks (≥90th altitude percentile), and tourism destination boundaries provided by Österreich Werbung – to obtain one indicator value per month and decade for each spatial unit.</p><h2 id="what-is-measured" tabindex="-1">What is measured <a class="header-anchor" href="#what-is-measured" aria-label="Permalink to &quot;What is measured&quot;">​</a></h2><ul><li><p><strong>Hot day</strong>s: days with a maximum temperature above 30°C</p></li><li><p><strong>Tropical nights</strong>: days with a minimum temperature above 20°C</p></li><li><p><strong>Beach/lake days</strong>: days with a maximum temperature above 23°C and more than 250 W/m² of daily mean solar radiation</p></li><li><p><strong>Ice days</strong>: days with a maximum temperature below 0°C</p></li><li><p><strong>Heat wave duration index (HWDI)</strong>: the annual count of days forming part of a run of at least three consecutive days on which the maximum temperature exceeds the 90th-percentile threshold, based on the 1961–1990 reference period</p></li><li><p><strong>Strong precipitation day</strong>s: days with 10 mm or more of precipitation</p></li><li><p><strong>Dry days</strong>: days with less than 1 mm of precipitation</p></li><li><p><strong>Strong wind days</strong>: days on which the mean wind speed exceeds 11.1 m/s</p></li></ul><h2 id="benefit-for-users" tabindex="-1">Benefit for users <a class="header-anchor" href="#benefit-for-users" aria-label="Permalink to &quot;Benefit for users&quot;">​</a></h2><ul><li><p>Tourism regions can compare climate data across several destinations and use this to build long-term strategies for sustainable tourism across an entire region.</p></li><li><p>Individual destinations get a clear picture of how their local climate is changing, informing climate-friendly development strategies.</p></li><li><p>Because projections run to 2100 under two scenarios, destinations can weigh a moderate against a high-emissions future and plan infrastructure adaptations accordingly, well ahead of time.</p></li></ul>',19))],64)):q("",!0)])]))}});export{b as __pageData,v as default};
